	["Colour And Size By Time Left"] = "Farbe und Größe nach Restzeit", -- draft
	["Timers turn red and larger under 5 seconds, yellow under a minute, and smaller for minutes and hours. Off: all white."] = "Timer werden unter 5 Sekunden rot und größer, unter einer Minute gelb und bei Minuten und Stunden kleiner. Aus: alle weiß.", -- draft
	-- Tweaks
	["Tweaks"] = "Anpassungen", -- draft
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "Blendet das Mikromenü und die Taschenleiste aus und skaliert den schwebenden Kampftext.", -- draft
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "Kleine Knöpfe mit großer Wirkung. Blende aus, was du nie anklickst, vergrößere, was du nie siehst.", -- draft
	["Hide Frames"] = "Fenster ausblenden", -- draft
	["Hide Micro Menu"] = "Mikromenü ausblenden", -- draft
	["Hides the micro menu. It shows in Edit Mode."] = "Blendet das Mikromenü aus. Im Bearbeitungsmodus wird es gezeigt.", -- draft
	["Hide Bag Bar"] = "Taschenleiste ausblenden", -- draft
	["Hides the bag bar. Your bag keys still work; it shows in Edit Mode."] = "Blendet die Taschenleiste aus. Deine Taschentasten funktionieren weiter; im Bearbeitungsmodus wird sie gezeigt.", -- draft
	["Hide Minimap Coordinates"] = "Koordinaten der Minikarte ausblenden", -- draft
