	["Bag Slots On Bag Window"] = "Taschenplätze am Taschenfenster", -- draft
	["With the bag bar hidden, the bag slots show under the bag window, so you can still swap bags."] = "Ist die Taschenleiste ausgeblendet, erscheinen die Taschenplätze unter dem Taschenfenster, damit du weiter Taschen tauschen kannst.", -- draft
	["Collapse Arrow"] = "Einklapp-Pfeil", -- draft
	["An arrow beside the backpack folds the bag slots away."] = "Ein Pfeil neben dem Rucksack klappt die Taschenplätze weg.", -- draft
	["Chat"] = "Chat", -- draft
	["Chat Notices"] = "Chathinweise", -- draft
	["MelloUI's own lines in the chat, like hints and learned entrances. Replies to commands always show."] = "MelloUIs eigene Zeilen im Chat, etwa Hinweise und gelernte Eingänge. Antworten auf Befehle erscheinen immer.", -- draft
	["Notices"] = "Hinweise", -- draft
	["On-screen Notices"] = "Hinweise auf dem Bildschirm", -- draft
	["A short line near the top of the screen when MelloUI has news, like a route set or finished. Move it in Edit Layout."] = "Eine kurze Zeile oben am Bildschirm, wenn MelloUI Neuigkeiten hat, etwa eine gesetzte oder beendete Route. Verschiebe sie mit Layout bearbeiten.", -- draft
	["Send To Chat Instead"] = "Stattdessen in den Chat", -- draft
	["The notices go to the chat instead of the screen."] = "Die Meldungen gehen in den Chat statt auf den Bildschirm.", -- draft
	["Notice Sounds"] = "Hinweistöne", -- draft
	["A short chime with each notice."] = "Ein kurzer Klang bei jeder Meldung.", -- draft
	["Text Shade"] = "Textschatten", -- draft
	["A soft dark shadow behind on-screen text (zone names, messages, names on unit frames and nameplates, chat tags on parchment), so it stays readable on bright ground."] = "Ein weicher dunkler Schatten hinter Bildschirmtext (Zonennamen, Meldungen, Namen auf Einheitenfenstern und Namensplaketten, Chatkürzel auf Pergament), damit er auf hellem Grund lesbar bleibt.", -- draft
	["Outlined Text"] = "Umrandeter Text", -- draft
	["An outline on MelloUI's on-screen text: notices, Combat Text, Gains and, with Text Shade on, the zone text and the messages in the middle of the screen. Off: soft text on a dark shadow."] = "Ein Umriss um MelloUIs Bildschirmtext: Meldungen, Kampftext, Gewinne und, mit Textschatten, der Zonentext und die Meldungen in der Bildschirmmitte. Aus: weicher Text auf dunklem Schatten.", -- draft
	["Combat Text"] = "Kampftext", -- draft
