	-- Services
	["Services"] = "Dienste", -- draft
	["Buttons under the minimap that route you to the nearest repair, mailbox, inn, flight master, bank or trainer."] = "Knöpfe unter der Minikarte, die dich zur nächsten Reparatur, zum Briefkasten, Gasthaus, Flugmeister, zur Bank oder zum Lehrer führen.", -- draft
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "Reparatur, Briefkasten, Gastwirt, Bank ... der nächste ist ein Klick unter der Minikarte.", -- draft
	["Icon Bar Under The Minimap"] = "Symbolleiste unter der Minikarte", -- draft
	["Buttons for nearby services (repair, trainers, flights...) under the minimap. Click one to get a route there; right-click stops it."] = "Knöpfe für Dienste in der Nähe (Reparatur, Lehrer, Flüge...) unter der Minikarte. Ein Klick legt eine Route dorthin; Rechtsklick stoppt sie.", -- draft
	["Button Layout"] = "Knopfanordnung", -- draft
	["Groups: one row of group buttons, each opening a list of services with distances. All Buttons: two rows, one icon per service."] = "Gruppen: eine Reihe Gruppenknöpfe, die je eine Liste der Dienste mit Entfernungen öffnen. Alle Knöpfe: zwei Reihen, ein Symbol pro Dienst.", -- draft
	["Groups"] = "Gruppen", -- draft
	["All Buttons"] = "Alle Knöpfe", -- draft
	["AddOns Group"] = "Addon-Gruppe", -- draft
	["Gathers other addons' minimap buttons into an AddOns group on the Services bar. Off: they go back on the minimap."] = "Sammelt die Minikartenknöpfe anderer Addons in einer Addons-Gruppe auf der Dienste-Leiste. Aus: sie kehren auf die Minikarte zurück.", -- draft
	["Bar Distance From The Minimap"] = "Abstand der Leiste von der Minikarte", -- draft
	["How far below the minimap the Services bar sits."] = "Wie weit unter der Minikarte die Dienste-Leiste sitzt.", -- draft
	["Round Icons"] = "Runde Symbole", -- draft
	["Service icons as round medallions instead of squares."] = "Dienstsymbole als runde Medaillons statt als Quadrate.", -- draft
	["Trays Slide Out"] = "Ausfahrende Listen", -- draft
	["A group's list slides out like a drawer."] = "Die Liste einer Gruppe gleitet heraus wie eine Schublade.", -- draft
	["Minimap Button"] = "Minikartenknopf", -- draft
	["A round button on the minimap's edge that opens the list of the nearest services. /services does the same."] = "Ein runder Knopf am Rand der Minikarte, der die Liste der nächsten Dienste öffnet. /services tut dasselbe.", -- draft
	-- Reminders
	["Reminders"] = "Erinnerungen", -- draft
	["A round button by your portrait for errands: restock, mail, repairs and trainers. Click it for a route there."] = "Ein runder Knopf an deinem Porträt für Besorgungen: Auffüllen, Post, Reparaturen und Lehrer. Ein Klick legt eine Route dorthin.", -- draft
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "Vorräte, Post, Reparaturen und Training: ein sanfter Stups neben deinem Porträt, nie ein Nörgeln.", -- draft
	["New Mail"] = "Neue Post", -- draft
	["Reminds you when mail is waiting."] = "Erinnert dich, wenn Post wartet.", -- draft
	["Repair Gear"] = "Ausrüstung reparieren", -- draft
	["Reminds you when your gear is wearing out."] = "Erinnert dich, wenn deine Ausrüstung verschleißt.", -- draft
	["Remind At"] = "Erinnern bei", -- draft
	["Reminds you when your most worn item is down to this durability."] = "Erinnert dich, wenn dein am meisten abgenutzter Gegenstand bei dieser Haltbarkeit ist.", -- draft
	["Trainer"] = "Lehrer", -- draft
	["Reminds you when a trainer has something new for you."] = "Erinnert dich, wenn ein Lehrer etwas Neues für dich hat.", -- draft
	["Class Spells"] = "Klassenzauber", -- draft
	["New class spells to learn."] = "Neue Klassenzauber zum Erlernen.", -- draft
	["Profession Ranks"] = "Berufsränge", -- draft
	["A new profession rank to learn."] = "Ein neuer Berufsrang zum Erlernen.", -- draft
	["Stay Up In Rest Areas"] = "In Erholungsgebieten bleiben", -- draft
	["In inns, cities and towns, reminders stay until done or until you leave."] = "In Gasthäusern, Städten und Orten bleiben Erinnerungen, bis sie erledigt sind oder du gehst.", -- draft
	["Widget"] = "Widget", -- draft
	["Place"] = "Platz", -- draft
	["Which side of your portrait the reminder button sits on. Detached or without a player frame, you move it in Edit Layout, and this is the side its line opens to."] = "Auf welcher Seite deines Porträts der Erinnerungsknopf sitzt. Losgelöst oder ohne Spielerfenster verschiebst du ihn mit Layout bearbeiten, und dies ist die Seite, zu der sich seine Zeile öffnet.", -- draft
	["Left of the portrait"] = "Links vom Porträt", -- draft
	["Above the portrait"] = "Über dem Porträt", -- draft
	["Right of the portrait"] = "Rechts vom Porträt", -- draft
	["Detach From Portrait"] = "Vom Porträt lösen", -- draft
	["Gives the reminder button a place of its own, so it no longer follows your player frame. Move it in Edit Layout."] = "Gibt dem Erinnerungsknopf einen eigenen Platz, sodass er deinem Spielerfenster nicht mehr folgt. Verschiebe ihn mit Layout bearbeiten.", -- draft
	["Glow"] = "Leuchten", -- draft
	["The soft glow around the reminder button: steady, or none."] = "Das weiche Leuchten um den Erinnerungsknopf: gleichmäßig oder keins.", -- draft
	["Steady"] = "Ruhig", -- draft
	["Show For"] = "Zeigen für", -- draft
	["How long a new reminder stays before tucking itself away."] = "Wie lange eine neue Erinnerung bleibt, bevor sie sich wegklappt.", -- draft
	["Lock The Widgets"] = "Widgets sperren", -- draft
	["Locks the widget column in place, also in Edit Layout."] = "Fixiert die Widget-Spalte an ihrem Platz, auch in Layout bearbeiten.", -- draft
	["Most Widgets Shown"] = "Höchstens gezeigte Widgets", -- draft
	["How many widgets show at once; the rest wait in a \"+ more\" row. Loot rolls, summons and ready checks always show."] = "Wie viele Widgets gleichzeitig erscheinen; der Rest wartet in einer Zeile + mehr. Beutewürfe, Herbeirufungen und Bereitschaftschecks erscheinen immer.", -- draft
	-- Restock
	["Restock"] = "Auffüllen", -- draft
	["Keeps food, drink, ammo and reagents stocked: a reminder when low, and a shopping list at merchants."] = "Hält Essen, Trinken, Munition und Reagenzien vorrätig: eine Erinnerung, wenn sie knapp werden, und eine Einkaufsliste bei Händlern.", -- draft
	["Water, bread and arrows, topped up before they run out."] = "Wasser, Brot und Pfeile, aufgefüllt, bevor sie ausgehen.", -- draft
	["Remind Below"] = "Erinnern unter", -- draft
	["Reminds you when an item drops below this share of its amount."] = "Erinnert dich, wenn ein Gegenstand unter diesen Anteil seiner Menge fällt.", -- draft
	["Shopping List At The Shop"] = "Einkaufsliste im Laden", -- draft
	["At a merchant, a shopping list of what you are low on. Nothing is bought until you click Buy."] = "Bei einem Händler eine Einkaufsliste dessen, was dir fehlt. Nichts wird gekauft, bis du auf Kaufen klickst.", -- draft
	["Restock List"] = "Auffüllliste", -- draft
	["What to keep in your bags, and how many. Each character has its own list. /restock opens it too."] = "Was du in deinen Taschen haben willst und wie viel. Jeder Charakter hat seine eigene Liste. /restock öffnet sie auch.", -- draft
	["Edit"] = "Bearbeiten", -- draft
	-- Widgets
	["Widgets"] = "Widgets", -- draft
	["Small live widgets in one column (loot rolls, summons, ready checks, whispers and more), and reminders by your portrait."] = "Kleine Live-Widgets in einer Spalte (Beutewürfe, Herbeirufungen, Bereitschaftschecks, Flüstern und mehr) und Erinnerungen an deinem Porträt.", -- draft
	["What needs you now, in one small column."] = "Was dich jetzt braucht, in einer kleinen Spalte.", -- draft
	["In The Column"] = "In der Spalte", -- draft
	["Loot Rolls"] = "Beutewürfe", -- draft
	["Group loot rolls, with Need, Greed and Pass."] = "Beutewürfe der Gruppe, mit Bedarf, Gier und Passen.", -- draft
	["Corpse Run"] = "Leichenlauf", -- draft
	["As a ghost: how far your body is. Click for the way there."] = "Als Geist: wie weit dein Körper entfernt ist. Ein Klick zeigt den Weg dorthin.", -- draft
