	-- Nameplates
	["Large crowd-control icon above the name and a quest marker on enemy nameplates."] = "Großes Kontrollverlust-Symbol über dem Namen und eine Questmarkierung auf gegnerischen Namensplaketten.", -- draft
	["Know who is stunned, who is your quest target, and who is about to be a problem."] = "Wisse, wer betäubt ist, wer dein Questziel ist und wer gleich ein Problem wird.", -- draft
	["Own Plate Size"] = "Eigene Plakettengröße", -- draft
	["The enemy plates take the width and height set here instead of the game's."] = "Die Gegnerplaketten erhalten die hier eingestellte Breite und Höhe statt der des Spiels.", -- draft
	["Plate Width"] = "Plakettenbreite", -- draft
	["The whole plate's width: the health bar and the level badge's room beside it."] = "Die Breite der ganzen Plakette: der Gesundheitsbalken und der Platz für das Stufenabzeichen daneben.", -- draft
	["Plate Height"] = "Plakettenhöhe", -- draft
	["The health bar's height."] = "Die Höhe des Gesundheitsbalkens.", -- draft
	["Crowd Control"] = "Kontrollverlust", -- draft
	["Large CC Icon Above Name"] = "Großes Kontrollverlust-Symbol über dem Namen", -- draft
	["A large crowd-control icon above the name. Needs the game's Crowd Control nameplate option on."] = "Ein großes Kontrollverlust-Symbol über dem Namen. Braucht die Kontrollverlust-Option des Spiels für Namensplaketten.", -- draft
	["CC Icon Size"] = "Größe des Kontrollverlust-Symbols", -- draft
	["The size of the crowd-control icon."] = "Die Größe des Kontrollverlust-Symbols.", -- draft
	["Gap Above Name"] = "Abstand über dem Namen", -- draft
	["The space between the name and the crowd-control icon."] = "Der Abstand zwischen Name und Kontrollverlust-Symbol.", -- draft
	["Mouseover Highlight"] = "Hervorhebung bei Mauskontakt", -- draft
	["A crisp outline on the plate under your mouse."] = "Ein klarer Umriss auf der Plakette unter deiner Maus.", -- draft
	["Quest Icon"] = "Questsymbol", -- draft
	["A quest marker on enemies you still need for a quest."] = "Eine Questmarkierung auf Feinden, die du noch für eine Quest brauchst.", -- draft
	["Quest Icon Size"] = "Größe des Questsymbols", -- draft
	["The size of the quest marker."] = "Die Größe der Questmarkierung.", -- draft
	["Threat Line"] = "Bedrohungslinie", -- draft
	["In group fights, a thin line on an enemy's bar showing how close it is to turning on you. For tanks, it turns red when you lose a mob."] = "In Gruppenkämpfen eine dünne Linie auf der Leiste eines Feindes, die zeigt, wie nah er daran ist, sich gegen dich zu wenden. Für Tanks wird sie rot, wenn du einen Gegner verlierst.", -- draft
	["Combo Points"] = "Combopunkte", -- draft
	["Rogues and cat druids: your combo points on your target's nameplate."] = "Schurken und Druiden in Katzengestalt: deine Combopunkte auf der Namensplakette deines Ziels.", -- draft
	["Combo Point Size"] = "Größe der Combopunkte", -- draft
	["The size of each combo point."] = "Die Größe jedes Combopunkts.", -- draft
	["Moves the combo points left or right on the nameplate."] = "Verschiebt die Combopunkte auf der Namensplakette nach links oder rechts.", -- draft
	["Moves the combo points up or down on the nameplate. The name moves out of their way."] = "Verschiebt die Combopunkte auf der Namensplakette nach oben oder unten. Der Name weicht ihnen aus.", -- draft
	["Swing Badge"] = "Schwungabzeichen", -- draft
	["Swing Badge Size"] = "Größe des Schlagabzeichens", -- draft
	["The size of your swing timer's weapon badge on your target's nameplate, or over the Personal Display."] = "Die Größe des Waffenabzeichens deines Schlagtimers auf der Namensplakette deines Ziels oder über der persönlichen Anzeige.", -- draft
	-- PlateImpact
	["Impact Effects"] = "Treffereffekte", -- draft
	["Your target's nameplate reacts to the fight: hits flash, crits glow, interrupted casts shatter."] = "Die Namensplakette deines Ziels reagiert auf den Kampf: Treffer blitzen, kritische Treffer leuchten, unterbrochene Zauber zerspringen.", -- draft
	["Every hit lands on the plate, not only in a number."] = "Jeder Treffer landet auf der Plakette, nicht nur in einer Zahl.", -- draft
	["Hit Flash"] = "Trefferblitz", -- draft
	["Your target's bar flashes when it is hit; gold for a critical hit."] = "Die Leiste deines Ziels blitzt bei einem Treffer auf; golden bei einem kritischen Treffer.", -- draft
	["Damage Chunk"] = "Schadensstück", -- draft
	["The part of the bar a hit took stays lit for a moment before it drains, so you see each hit's size."] = "Der Teil der Leiste, den ein Treffer nahm, leuchtet kurz, bevor er abläuft, damit du die Größe jedes Treffers siehst.", -- draft
	["Crit Glow"] = "Kritisches Leuchten", -- draft
	["A gold glow bursts around your target's bar on a critical hit."] = "Ein goldenes Leuchten bricht bei einem kritischen Treffer um die Leiste deines Ziels hervor.", -- draft
	["Kill Flash"] = "Todesblitz", -- draft
	["A killing blow flashes the bar out instead of the plate just vanishing."] = "Ein tödlicher Schlag lässt die Leiste aufblitzen, statt die Plakette einfach verschwinden zu lassen.", -- draft
	["Dodge And Miss"] = "Ausweichen und Verfehlen", -- draft
	["Dodge, parry and miss words flick off the side of your target's plate."] = "Ausweichen, Parieren und Verfehlen schnellen als Wörter von der Seite der Plakette deines Ziels.", -- draft
	["Cast Warning"] = "Zauberwarnung", -- draft
	["Your target's cast bar glows hotter near the end, and shatters when interrupted."] = "Die Zauberleiste deines Ziels glüht gegen Ende heißer und zerspringt bei einer Unterbrechung.", -- draft
	["On Your Target Frame"] = "Auf deinem Zielfenster", -- draft
	["Your target frame's health bar shows the same hit effects."] = "Die Gesundheitsleiste deines Zielfensters zeigt dieselben Treffereffekte.", -- draft
	-- Tooltip
	["Tooltip"] = "Tooltip", -- draft
	["Dark flat tooltips with class coloured names and borders, plus placement options."] = "Dunkle flache Tooltips mit Namen und Rändern in Klassenfarbe, dazu Optionen zur Platzierung.", -- draft
	["Dark, flat and out of the way, with names in the colour of their class."] = "Dunkel, flach und aus dem Weg, mit Namen in der Farbe ihrer Klasse.", -- draft
	["Background"] = "Hintergrund", -- draft
	["The tooltips' background: Dark, the game's own, or (with Oldschool) Painted or Parchment."] = "Der Hintergrund der Tooltips: Dunkel, der des Spiels oder (mit Oldschool) Gemalt oder Pergament.", -- draft
	["Painted"] = "Gemalt", -- draft
	["Parchment"] = "Pergament", -- draft
	["Dark"] = "Dunkel", -- draft
	["Game"] = "Spiel", -- draft
	["Backdrop Opacity"] = "Deckkraft des Hintergrunds", -- draft
	["How solid the Dark background is."] = "Wie deckend der dunkle Hintergrund ist.", -- draft
	["Class / Reaction Border"] = "Rand nach Klasse / Reaktion", -- draft
	["Colours a unit tooltip's border by class (players) or reaction (NPCs)."] = "Färbt den Rand eines Einheiten-Tooltips nach Klasse (Spieler) oder Gesinnung (NPCs).", -- draft
	["Units"] = "Einheiten", -- draft
	["Class / Reaction Health Colour"] = "Gesundheitsfarbe nach Klasse / Reaktion", -- draft
	["The tooltip's health bar in the class or reaction colour instead of green."] = "Die Gesundheitsleiste des Tooltips in Klassen- oder Gesinnungsfarbe statt grün.", -- draft
	["Hide Health Bar"] = "Gesundheitsbalken ausblenden", -- draft
	["Hides the health bar under unit tooltips."] = "Blendet die Gesundheitsleiste unter Einheiten-Tooltips aus.", -- draft
	["Hide Issue Report Line"] = "Zeile zum Fehlerbericht ausblenden", -- draft
	["Hides the beta's \"Press F6 to submit an issue\" line in tooltips."] = "Blendet die Beta-Zeile Drücke F6, um ein Problem zu melden in Tooltips aus.", -- draft
	["Coloured Lines"] = "Farbige Zeilen", -- draft
	["Colours tooltip lines: guild, faction, level difficulty and quest progress."] = "Färbt Tooltipzeilen: Gilde, Fraktion, Stufenschwierigkeit und Questfortschritt.", -- draft
	["Hide Unit Tooltips In Combat"] = "Einheiten-Tooltips im Kampf ausblenden", -- draft
	["No unit tooltips in combat."] = "Keine Einheiten-Tooltips im Kampf.", -- draft
	["Fade Delay"] = "Ausblendverzögerung", -- draft
	["How long a tooltip stays after your mouse leaves."] = "Wie lange ein Tooltip bleibt, nachdem deine Maus ihn verlässt.", -- draft
	["Placement"] = "Platzierung", -- draft
	["Anchor"] = "Anker", -- draft
	["Where tooltips appear."] = "Wo Tooltips erscheinen.", -- draft
	["Default (Edit Mode position)"] = "Standard (Bearbeitungsmodus)", -- draft
	["At the cursor"] = "Am Mauszeiger", -- draft
	["Right of the cursor"] = "Rechts vom Mauszeiger", -- draft
	["Scale"] = "Skalierung", -- draft
	["The size of tooltips."] = "Die Größe der Tooltips.", -- draft
	-- UnitFrames
	["Centred names, a clear name band and no combat flash for player, target and focus; the party's levels and the names' soft bands."] = "Zentrierte Namen, ein klares Namensband und kein Kampfblinken für Spieler, Ziel und Fokus; die Stufen der Gruppe und die weichen Streifen der Namen.", -- draft
	["Player, target and focus, centred and calm."] = "Spieler, Ziel und Fokus, zentriert und ruhig.", -- draft
	["MelloUI Frames"] = "MelloUI-Fenster", -- draft
	["The unit frames in MelloUI's look: a gold portrait ring, a level badge and gold-lined borders. Off: the game's own art."] = "Die Einheitenfenster in MelloUIs Aussehen: ein goldener Porträtring, ein Stufenabzeichen und goldgesäumte Ränder. Aus: die Grafik des Spiels.", -- draft
	["Target of Target"] = "Ziel des Ziels", -- draft
	["Shows who your target is targeting, under the target frame, and who your focus is targeting, under the focus frame. This is the game's own Target of Target setting. A change here takes effect after a /reload."] = "Zeigt unter dem Zielfenster, wen dein Ziel anvisiert, und unter dem Fokusfenster, wen dein Fokus anvisiert. Das ist die Spieleinstellung „Ziel des Ziels“. Eine Änderung hier wirkt nach einem /reload.", -- draft
	["Flip Horizontally"] = "Horizontal spiegeln", -- draft
	["Mirrors the party frames for a party on the right of the screen: portraits on the right."] = "Spiegelt die Gruppenfenster für eine Gruppe am rechten Bildschirmrand: Porträts rechts.", -- draft
	["Names"] = "Namen", -- draft
	["Name Font"] = "Namensschrift", -- draft
	["The font of names on the unit frames and party portraits. Shared: the interface font."] = "Die Schrift der Namen auf Einheitenfenstern und Gruppenporträts. Gemeinsam: die Oberflächenschrift.", -- draft
	["Glows"] = "Leuchten", -- draft
	["Hide Combat Flash"] = "Kampfblinken ausblenden", -- draft
	["Hides the threat glow on the unit frames. Off: a soft halo round each frame's own shape while it has threat, amber when close to pulling, red while holding the enemy."] = "Blendet das Bedrohungsleuchten an den Einheitenfenstern aus. Aus: ein sanfter Schein um die Form jedes Fensters, solange es Bedrohung hat, bernsteinfarben kurz vor dem Pullen, rot, während es den Gegner hält.", -- draft
	["Hide Status Glow"] = "Statusleuchten ausblenden", -- draft
	["Hides the resting and combat glow around your portrait, and your pet's attack glow."] = "Blendet das Erholungs- und Kampfleuchten um dein Porträt und das Angriffsleuchten deines Begleiters aus.", -- draft
	["Hide PvP Badge"] = "PvP-Abzeichen ausblenden", -- draft
	["Hides the PvP badge beside the portraits."] = "Blendet das PvP-Abzeichen neben den Porträts aus.", -- draft
	["Hide Heal Numbers"] = "Heilungszahlen ausblenden", -- draft
	["Your portrait no longer shows the green numbers of the heals you take. Damage, misses and mana gains still show."] = "Dein Porträt zeigt die grünen Zahlen der Heilungen, die du erhältst, nicht mehr. Schaden, Fehlschläge und Managewinne erscheinen weiterhin.", -- draft
	["Frame Art"] = "Fenstergrafik", -- draft
	-- Fader
	["Fader"] = "Ausblender", -- draft
	["Fades parts of the interface while you don't need them: out of combat, or until you point at them."] = "Blendet Teile der Oberfläche aus, solange du sie nicht brauchst: außerhalb des Kampfes oder bis du auf sie zeigst.", -- draft
	["Your interface, only when you need it."] = "Deine Oberfläche, nur wenn du sie brauchst.", -- draft
	["Fade Everything"] = "Alles ausblenden", -- draft
	["Sets every part below to In Combat: the interface fades out of combat and comes back in a fight."] = "Setzt jeden Teil unten auf Im Kampf: die Oberfläche blendet außerhalb des Kampfes aus und kehrt im Kampf zurück.", -- draft
	["Fade"] = "Ausblenden", -- draft
	["Fade Nothing"] = "Nichts ausblenden", -- draft
	["Sets every part below to Always: nothing fades."] = "Setzt jeden Teil unten auf Immer: nichts blendet aus.", -- draft
	["Reset"] = "Zurücksetzen", -- draft
	["Faded Opacity"] = "Deckkraft ausgeblendet", -- draft
	["How visible a faded part stays. 0%: hidden until needed."] = "Wie sichtbar ein ausgeblendeter Teil bleibt. 0%: versteckt, bis er gebraucht wird.", -- draft
	["Fade After"] = "Ausblenden nach", -- draft
	["How long a part waits before fading, after a fight or after your mouse leaves."] = "Wie lange ein Teil wartet, bevor er ausblendet, nach einem Kampf oder nachdem deine Maus ihn verlässt.", -- draft
	["Fade Speed"] = "Ausblendgeschwindigkeit", -- draft
	["How long the fade takes. Coming back is always quick."] = "Wie lange das Ausblenden dauert. Das Zurückkommen ist immer schnell.", -- draft
	["Show With A Target"] = "Mit Ziel zeigen", -- draft
	["In Combat parts also come back while you have a target."] = "Im-Kampf-Teile kehren auch zurück, solange du ein Ziel hast.", -- draft
	["Also Show On Mouseover"] = "Auch beim Darüberfahren zeigen", -- draft
	["In Combat parts also come back while your mouse is over them."] = "Im-Kampf-Teile kehren auch zurück, solange deine Maus über ihnen ist.", -- draft
	["Your own frame. In Combat, it also returns while you are hurt, low on mana or dead. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Dein eigenes Fenster. Im Kampf kehrt es auch zurück, solange du verletzt bist, wenig Mana hast oder tot bist. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Pet Frame Too"] = "Auch Begleiterrahmen", -- draft
	["Your pet's frame fades with the player frame and returns while your pet is hurt."] = "Das Fenster deines Begleiters blendet mit dem Spielerfenster aus und kehrt zurück, solange dein Begleiter verletzt ist.", -- draft
	["Your target's frame and its target. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Das Fenster deines Ziels und dessen Ziel. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Your focus's frame. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Das Fenster deines Fokus. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Party Frames"] = "Gruppenrahmen", -- draft
	["The party frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Gruppenfenster. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The raid frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Schlachtzugsfenster. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Your buffs and debuffs. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Deine Stärkungs- und Schwächungszauber. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The reminder buttons beside your portrait. A new reminder doesn't bring them back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Erinnerungsknöpfe neben deinem Porträt. Eine neue Erinnerung holt sie nicht zurück. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The Personal Display's bars. In Combat, they also return while you cast. Always: never faded. In Combat: faded out of combat."] = "Die Leisten der Persönlichen Anzeige. Im Kampf kehren sie auch zurück, solange du zauberst. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet.", -- draft
	["Main Action Bar"] = "Hauptaktionsleiste", -- draft
	["The main action bar. Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Hauptaktionsleiste. Ihre Tasten funktionieren auch ausgeblendet. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Ihre Tasten funktionieren auch ausgeblendet. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Stance & Pet Bar"] = "Haltungs- & Begleiterleiste", -- draft
	["The stance, form and pet bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Haltungs-, Gestalt- und Begleiterleisten. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Micro Menu"] = "Mikromenü", -- draft
	["The micro menu. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Das Mikromenü. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Bag Bar"] = "Taschenleiste", -- draft
	["The bag bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Taschenleiste. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The experience and reputation bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Erfahrungs- und Rufleisten. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The chat windows, tabs and buttons. They return while you type. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Chatfenster, Reiter und Knöpfe. Sie kehren zurück, solange du tippst. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The minimap and the Services bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Minikarte und die Dienste-Leiste. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Quest Tracker"] = "Questverfolgung", -- draft
	["MelloUI's Quest Tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "MelloUIs Questverfolgung. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Objective Tracker"] = "Questzielverfolgung", -- draft
	["The game's objective tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Zielverfolgung des Spiels. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["Widget Column"] = "Widget-Spalte", -- draft
	["The widget column. A new widget doesn't bring it back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Widget-Spalte. Ein neues Widget holt sie nicht zurück. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["World Marker"] = "Weltmarkierung", -- draft
	["Route's World Marker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die Weltmarkierung der Route. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	["The FPS and latency readout. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Die FPS- und Latenzanzeige. Immer: nie ausgeblendet. Im Kampf: außerhalb des Kampfes ausgeblendet. Bei Mauskontakt: ausgeblendet, bis du darauf zeigst.", -- draft
	-- QuestAuto
	["Auto Accept & Hand In"] = "Automatisch annehmen & abgeben", -- draft
	["Accepts quests and hands them in as you talk to their givers, off until you switch it on."] = "Nimmt Quests an und gibt sie ab, während du mit ihren Questgebern sprichst, aus, bis du es einschaltest.", -- draft
	["Talk, and the quest is yours. Hold Shift to read it first."] = "Sprich, und die Quest gehört dir. Halte Umschalt, um sie zuerst zu lesen.", -- draft
	["Auto Accept Quests"] = "Quests automatisch annehmen", -- draft
	["Accepts quests as soon as a giver offers them. Repeatable, daily and shared quests are left to you."] = "Nimmt Quests an, sobald ein Questgeber sie anbietet. Wiederholbare, tägliche und geteilte Quests bleiben dir überlassen.", -- draft
	["Auto Hand In"] = "Automatisch abgeben", -- draft
	["Hands in finished quests as soon as you talk to the NPC. A choice of rewards waits for you."] = "Gibt fertige Quests ab, sobald du mit dem NPC sprichst. Eine Auswahl an Belohnungen wartet auf dich.", -- draft
	["Take The Upgrade"] = "Verbesserung nehmen", -- draft
	["With a choice of rewards, takes the best upgrade you can use, or the one that sells for the most."] = "Bei einer Auswahl an Belohnungen nimmt es die beste Verbesserung, die du nutzen kannst, oder die, die am meisten einbringt.", -- draft
	["Skip Key"] = "Taste zum Überspringen", -- draft
	["Hold this key while talking to an NPC to stop the automatic accept and hand-in."] = "Halte diese Taste beim Sprechen mit einem NPC, um das automatische Annehmen und Abgeben zu stoppen.", -- draft
	["Shift"] = "Umschalt", -- draft
	["Ctrl"] = "Strg", -- draft
	["Alt"] = "Alt", -- draft
	-- HealerFrames
	["Healer Frames"] = "Heilerfenster", -- draft
	["Incoming heals on the unit frames, and a glow in a debuff's colour round any frame whose unit has a debuff to remove."] = "Eintreffende Heilungen auf den Einheitenfenstern und ein Leuchten in der Farbe eines Schwächungszaubers um jedes Fenster, dessen Einheit einen entfernbaren Schwächungszauber hat.", -- draft
	["See the heals coming in, and who needs a cleanse."] = "Sieh die Heilungen kommen und wer eine Reinigung braucht.", -- draft
	["Incoming Heals"] = "Eintreffende Heilungen", -- draft
	["Incoming heals and shields shown on the player, target and focus health bars."] = "Eingehende Heilungen und Schilde auf den Gesundheitsleisten von Spieler, Ziel und Fokus.", -- draft
	["Debuff Glow"] = "Schwächungsleuchten", -- draft
	["A glow in the debuff's colour around a friend's frame while they have a debuff that can be removed."] = "Ein Leuchten in der Farbe des Schwächungszaubers um das Fenster eines Verbündeten, solange er einen entfernbaren Schwächungszauber hat.", -- draft
	["Debuff Glow Shows"] = "Schwächungsleuchten zeigt", -- draft
	["Which debuffs light a frame: any that can be removed, the ones your group can remove, or only yours."] = "Welche Schwächungszauber ein Fenster leuchten lassen: jeder entfernbare, die, die deine Gruppe entfernen kann, oder nur deine.", -- draft
	["Every Dispellable Debuff"] = "Jeder bannbare Schwächungszauber", -- draft
	["Ones The Group Can Dispel"] = "Die die Gruppe bannen kann", -- draft
	["Ones I Can Dispel"] = "Die ich bannen kann", -- draft
	-- ActionBars
	["MelloUI on the bars: its own action, stance, pet and possess bars, micro menu, bag bar and experience bars, with their backdrops, button frames, colours and timers. Off: the game's own bars, untouched."] = "MelloUI auf den Leisten: eigene Aktions-, Haltungs-, Begleiter- und Besessenheitsleisten, Mikromenü, Taschenleiste und Erfahrungsleisten, mit ihren Hintergründen, Tastenrahmen, Farben und Timern. Aus: die eigenen Leisten des Spiels, unberührt.", -- draft
	["The experience and reputation bars in MelloUI's look. Off: the game's own frame."] = "Die Erfahrungs- und Rufleisten in MelloUIs Aussehen. Aus: der Rahmen des Spiels.", -- draft
	["Hide Page Arrows"] = "Seitenpfeile ausblenden", -- draft
	["Hides the main bar's page number and arrows. Paging keys still work."] = "Blendet Seitenzahl und Pfeile der Hauptleiste aus. Die Blättertasten funktionieren weiter.", -- draft
	["Hide Bar Art"] = "Leistenverzierung verbergen", -- draft
	["Hides the main bar's art, like the other bars. With UI Modifications off: only on your own Edit Mode layouts, after a /reload."] = "Blendet die Grafik der Hauptleiste aus, wie bei den anderen Leisten. Ohne UI-Änderungen: nur in deinen eigenen Bearbeitungsmodus-Layouts, nach einem /reload.", -- draft
