	["A backdrop around Action Bar 3. Neighbours with a backdrop share one."] = "Ein Hintergrund um Aktionsleiste 3. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around Action Bar 4. Neighbours with a backdrop share one."] = "Ein Hintergrund um Aktionsleiste 4. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around Action Bar 5. Neighbours with a backdrop share one."] = "Ein Hintergrund um Aktionsleiste 5. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around Action Bar 6. Neighbours with a backdrop share one."] = "Ein Hintergrund um Aktionsleiste 6. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around Action Bar 7. Neighbours with a backdrop share one."] = "Ein Hintergrund um Aktionsleiste 7. Nachbarn mit Hintergrund teilen sich einen.", -- draft
