	["A backdrop around the stance bar. Neighbours with a backdrop share one."] = "Ein Hintergrund um die Haltungsleiste. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around the pet bar. Neighbours with a backdrop share one."] = "Ein Hintergrund um die Begleiterleiste. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["Possess Bar"] = "Besessenheitsleiste", -- draft
	["A backdrop around the possess bar. Neighbours with a backdrop share one."] = "Ein Hintergrund um die Besessenheitsleiste. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["Totem Bar"] = "Totemleiste", -- draft
	["A backdrop around the totem bar. Neighbours with a backdrop share one."] = "Ein Hintergrund um die Totemleiste. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around the micro menu. Neighbours with a backdrop share one."] = "Ein Hintergrund um das Mikromenü. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["A backdrop around the bag bar. Neighbours with a backdrop share one."] = "Ein Hintergrund um die Taschenleiste. Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["Experience Bar"] = "Erfahrungsleiste", -- draft
	["A backdrop around the experience bar (the reputation bar in its place at the top level). Neighbours with a backdrop share one."] = "Ein Hintergrund um die Erfahrungsleiste (auf Höchststufe die Rufleiste an ihrer Stelle). Nachbarn mit Hintergrund teilen sich einen.", -- draft
	["Reputation Bar"] = "Rufleiste", -- draft
	["A backdrop around the second status bar (a watched reputation while you level). Neighbours with a backdrop share one."] = "Ein Hintergrund um die zweite Statusleiste (ein beobachteter Ruf während des Levelns). Nachbarn mit Hintergrund teilen sich einen.", -- draft
	-- ActionButtons
	["Action Buttons"] = "Aktionstasten", -- draft
	["Lights an action button while its key is held, and colours its icon by range and resources."] = "Lässt eine Aktionstaste leuchten, solange ihre Taste gehalten wird, und färbt ihr Symbol nach Reichweite und Ressourcen.", -- draft
	["See which button you press, and which spell cannot reach its target."] = "Sieh, welche Taste du drückst und welcher Zauber sein Ziel nicht erreicht.", -- draft
	["Action buttons in MelloUI's frame: gold when active, red out of range. Off: the game's own frames."] = "Aktionsknöpfe in MelloUIs Rahmen: golden, wenn aktiv, rot außer Reichweite. Aus: die Rahmen des Spiels.", -- draft
	["Cooldown Ready Flash"] = "Blitz bei bereiter Abklingzeit", -- draft
	["A gold light runs around a button when its cooldown ends."] = "Ein goldenes Licht läuft um einen Knopf, wenn seine Abklingzeit endet.", -- draft
	["Light While Pressed"] = "Leuchten beim Drücken", -- draft
	["A button lights up while you press it."] = "Ein Knopf leuchtet auf, während du ihn drückst.", -- draft
	["Range And Resource Colours"] = "Farben für Reichweite und Ressourcen", -- draft
	["Icons turn red out of range, blue without enough mana, and grey when unusable."] = "Symbole werden rot außer Reichweite, blau ohne genug Mana und grau, wenn sie unbenutzbar sind.", -- draft
	-- CooldownTweaks
	["Cooldown Manager Tweaks"] = "Anpassungen des Abklingzeitmanagers", -- draft
	["Centred rows, key bindings, a light while pressed and the count size on the game's Cooldown Manager."] = "Zentrierte Reihen, Tastenbelegungen, ein Leuchten beim Drücken und die Größe der Zähler am Abklingzeitmanager des Spiels.", -- draft
	["Your cooldowns, in the middle, with their keys on them."] = "Deine Abklingzeiten, in der Mitte, mit ihren Tasten darauf.", -- draft
	["Centre Rows"] = "Reihen zentrieren", -- draft
	["A shorter row of cooldown icons sits centred under the others."] = "Eine kürzere Reihe von Abklingzeitsymbolen sitzt zentriert unter den anderen.", -- draft
	["Key Bindings"] = "Tastenbelegungen", -- draft
	["The key bound to a cooldown's spell, on the icon's corner."] = "Die Taste, die auf den Zauber einer Abklingzeit gelegt ist, in der Ecke des Symbols.", -- draft
	["A cooldown's icon lights up while you press its action button."] = "Das Symbol einer Abklingzeit leuchtet, während du ihren Aktionsknopf drückst.", -- draft
	["Count Size"] = "Zählergröße", -- draft
	["The size of the charges and stacks numbers on the icons."] = "Die Größe der Ladungs- und Stapelzahlen auf den Symbolen.", -- draft
	-- BagWindow
	["Bags by Kind"] = "Taschen nach Art", -- draft
	["Your bags in one window, sorted by kind: new items, gear, quest items, consumables, junk and more."] = "Deine Taschen in einem Fenster, nach Art sortiert: neue Gegenstände, Ausrüstung, Questgegenstände, Verbrauchsgüter, Plunder und mehr.", -- draft
	["A place for everything, and everything under its heading."] = "Ein Platz für alles, und alles unter seiner Überschrift.", -- draft
	["Kinds"] = "Arten", -- draft
	["The kinds your bag window sorts items into, top first. Drag to reorder, untick to hide, Add kind to make your own; double-click a name to rename it, its cog opens its settings."] = "Die Arten, nach denen dein Taschenfenster Gegenstände sortiert, die oberste zuerst. Ziehen zum Umordnen, Haken entfernen zum Ausblenden, Art hinzufügen für eigene; Doppelklick auf einen Namen benennt ihn um, sein Zahnrad öffnet seine Einstellungen.", -- draft
	["Items You Placed"] = "Gegenstände, die du platziert hast", -- draft
	["While you hold an item, drop it on a kind's + to always sort it there. Forget puts every placed item back."] = "Während du einen Gegenstand hältst, lege ihn auf das + einer Art, um ihn immer dort einzusortieren. Vergessen setzt alle platzierten Gegenstände zurück.", -- draft
	["Forget"] = "Vergessen", -- draft
	["Bank by Kind"] = "Bank nach Art", -- draft
	["Your bank sorted by the same kinds as your bags. Off: the game's grid."] = "Deine Bank nach denselben Arten sortiert wie deine Taschen. Aus: das Raster des Spiels.", -- draft
	["Recent Lasts"] = "„Neu“ hält", -- draft
	["How long new items stay under Recent: until you close your bags, until you point at them, or 5 minutes."] = "Wie lange neue Gegenstände unter Neu bleiben: bis du die Taschen schließt, bis du auf sie zeigst oder 5 Minuten.", -- draft
	["Until The Bags Close"] = "Bis die Taschen schließen", -- draft
	["Until Hovered"] = "Bis zum Darüberfahren", -- draft
	["For 5 Minutes"] = "5 Minuten lang", -- draft
	["Columns"] = "Spalten", -- draft
	["How many slots wide the bag window is."] = "Wie viele Plätze breit das Taschenfenster ist.", -- draft
	["Item Size"] = "Gegenstandsgröße", -- draft
	["The size of the item slots. 37 is the game's size."] = "Die Größe der Gegenstandsplätze. 37 ist die Größe des Spiels.", -- draft
	["Fold Empty Slots"] = "Leere Plätze zusammenfalten", -- draft
	["All empty slots shown as one, with their count."] = "Alle leeren Plätze als einer gezeigt, mit ihrer Anzahl.", -- draft
	["Special Bags"] = "Spezialtaschen", -- draft
	["Items in a special bag (a mining bag, an herb bag, an ammo pouch, a quiver ...) wear that bag's colour, and the window's foot lists those bags with how full they are."] = "Gegenstände in einer Spezialtasche (Bergbautasche, Kräutertasche, Munitionsbeutel, Köcher ...) tragen die Farbe dieser Tasche, und der Fuß des Fensters listet diese Taschen mit ihrem Füllstand auf.", -- draft
	["Sort Items By"] = "Sortieren nach", -- draft
	["How items are ordered inside each kind."] = "Wie Gegenstände innerhalb jeder Art geordnet werden.", -- draft
	["Quality"] = "Qualität", -- draft
	["Name"] = "Name", -- draft
	["Newest First"] = "Neueste zuerst", -- draft
	["Item Level"] = "Gegenstandsstufe", -- draft
	["Loot Flight"] = "Beuteflug", -- draft
	["Looted items fly into your bag window; the rarer the item, the bigger the effect."] = "Geplünderte Gegenstände fliegen in dein Taschenfenster; je seltener, desto größer der Effekt.", -- draft
	["Items Glide"] = "Gleitende Gegenstände", -- draft
	["Items glide to their new slots instead of jumping."] = "Gegenstände gleiten an ihre neuen Plätze, statt zu springen.", -- draft
	["Rolling Money"] = "Rollendes Geld", -- draft
	["Your money counts up or down to its new amount."] = "Dein Geld zählt zu seinem neuen Betrag hoch oder herunter.", -- draft
	["Bags Full Warning"] = "Warnung bei vollen Taschen", -- draft
	["The bag window shakes and flashes red when your bags are full."] = "Das Taschenfenster wackelt und blinkt rot, wenn deine Taschen voll sind.", -- draft
	-- MinimapPanel
	["MelloUI's minimap: its size, square shape and the Services bar under it. Off: the game's own minimap."] = "MelloUIs Minikarte: ihre Größe, die quadratische Form und die Dienste-Leiste darunter. Aus: die Minikarte des Spiels.", -- draft
	["Shape"] = "Form", -- draft
	["The painted minimap's shape: round in its ring, or square in the Square Border."] = "Die Form der gemalten Minikarte: rund in ihrem Ring oder quadratisch im quadratischen Rand.", -- draft
	["Round"] = "Rund", -- draft
	["Square"] = "Eckig", -- draft
	["Square Border"] = "Eckiger Rand", -- draft
	["The border around the square minimap. Painted borders need Oldschool's painted Minimap."] = "Der Rand um die quadratische Minikarte. Gemalte Ränder brauchen die gemalte Minikarte von Oldschool.", -- draft
