	-- QuestTracker
	["MelloUI's quest tracker in the game's tracker's place. It scrolls, so every quest fits."] = "MelloUIs Questverfolgung an der Stelle der Verfolgung des Spiels. Sie scrollt, damit jede Quest passt.", -- draft
	["Every watched quest within reach: the tracker scrolls when the list runs long."] = "Jede beobachtete Quest in Reichweite: Die Verfolgung scrollt, wenn die Liste lang wird.", -- draft
	["Tracker"] = "Verfolgung", -- draft
	["How tall the tracker grows before it scrolls. You can also drag its corner."] = "Wie hoch die Verfolgung wird, bevor sie scrollt. Du kannst auch ihre Ecke ziehen.", -- draft
	["Match The Minimap's Width"] = "Breite der Minikarte übernehmen", -- draft
	["The tracker is as wide as the minimap and sits right under it, following it. Off: use Width below."] = "Die Verfolgung ist so breit wie die Minikarte und sitzt direkt darunter, ihr folgend. Aus: nutze Weite unten.", -- draft
	["How wide the tracker is when it doesn't match the minimap. You can also drag its corner."] = "Wie breit die Verfolgung ist, wenn sie nicht der Minikarte entspricht. Du kannst auch ihre Ecke ziehen.", -- draft
	["The size of quest titles and section headers. Objectives are one size smaller."] = "Die Größe von Questtiteln und Abschnittsüberschriften. Questziele sind eine Größe kleiner.", -- draft
	["Header Text Size"] = "Textgröße der Überschriften", -- draft
	["The size of the tracker's title."] = "Die Größe des Titels der Verfolgung.", -- draft
	["Background Opacity"] = "Hintergrunddeckkraft", -- draft
	["How solid the tracker's background is. At 0% its lines stand on the world, as the game's tracker's do."] = "Wie deckend der Hintergrund der Questverfolgung ist. Bei 0 % stehen ihre Zeilen direkt auf der Welt, wie die der Questverfolgung des Spiels.", -- draft
	["Scroll Step"] = "Scrollschritt", -- draft
	["How far one turn of the mouse wheel scrolls."] = "Wie weit eine Drehung des Mausrads scrollt.", -- draft
	["A quest's usable item beside it. Click to use it out of combat."] = "Der benutzbare Gegenstand einer Quest daneben. Ein Klick benutzt ihn außerhalb des Kampfes.", -- draft
	["Progress Motion"] = "Fortschrittsbewegung", -- draft
	["Counts roll to their new number, finished objectives get a tick, and a finished quest lights up."] = "Zähler rollen zur neuen Zahl, erfüllte Ziele bekommen einen Haken und eine fertige Quest leuchtet auf.", -- draft
	["Nearest First"] = "Nächste zuerst", -- draft
