	["back under the minimap (or on the game's tracker's place)"] = "zurück unter die Minikarte (oder an den Platz der Verfolgung des Spiels)", -- draft
	-- ErrorFilter
	["Hide the red error messages you choose, such as \"Not enough energy\" or \"Spell is not ready yet\", from the middle of the screen."] = "Blendet die roten Fehlermeldungen, die du wählst, etwa „Nicht genug Energie“ oder „Der Zauber ist noch nicht bereit.“, in der Bildschirmmitte aus.", -- draft
	["Quiet, please. The red shouts in the middle of the screen, a kind at a time."] = "Ruhe, bitte. Die roten Rufe in der Bildschirmmitte, eine Art nach der anderen.", -- draft
	["Hide"] = "Ausblenden", -- draft
	["Not Enough Resources"] = "Nicht genug Ressourcen", -- draft
