	["The font of names on the party and raid frames. Shared: the interface font."] = "Die Schrift der Namen auf Gruppen- und Schlachtzugsfenstern. Gemeinsam: die Oberflächenschrift.", -- draft
	["Health Text Font"] = "Schrift des Gesundheitstexts", -- draft
	["The font of health text and status words on the party and raid frames. Shared: the interface font."] = "Die Schrift von Gesundheitstext und Statuswörtern auf Gruppen- und Schlachtzugsfenstern. Gemeinsam: die Oberflächenschrift.", -- draft
	["Indicator Numbers Font"] = "Schrift der Anzeigenzahlen", -- draft
