	["Your aura indicators on the frames."] = "Deine Aurenindikatoren auf den Fenstern.", -- draft
	["Your Indicators"] = "Deine Anzeigen", -- draft
	["Your spell groups for this spec: drag a group onto the frame, pick its spells, then its look, place, size and colour."] = "Deine Zaubergruppen für diese Spezialisierung: ziehe eine Gruppe auf das Fenster, wähle ihre Zauber, dann Aussehen, Platz, Größe und Farbe.", -- draft
	-- PersonalDisplay
	["Your health, power and cast bars under your character, with a shield bar beside them. Place it in Edit Layout. Replaces the game's personal resource display."] = "Deine Gesundheits-, Kraft- und Zauberleisten unter deinem Charakter, mit einer Schildleiste daneben. Platziere sie mit Layout bearbeiten. Ersetzt die persönliche Ressourcenanzeige des Spiels.", -- draft
	["Health, power, casts and shields, right by your character."] = "Gesundheit, Ressource, Zauber und Schilde, direkt bei deinem Charakter.", -- draft
	["Shield Column"] = "Schildspalte", -- draft
	["A bar beside your character for all your shields, each in its school's colour. It drains as they take hits."] = "Eine Leiste neben deinem Charakter für alle deine Schilde, jeder in der Farbe seiner Schule. Sie leert sich, wenn sie Treffer nehmen.", -- draft
	["Hide The Game's Cast Bar"] = "Zauberbalken des Spiels ausblenden", -- draft
	["Hides the game's cast bar; your casts show on the display."] = "Blendet die Zauberleiste des Spiels aus; deine Zauber erscheinen auf der Anzeige.", -- draft
	["Heal Light From Your Character"] = "Heilungslicht von deinem Charakter", -- draft
	["Your heals' light starts from your character instead of the cast bar."] = "Das Licht deiner Heilungen startet an deinem Charakter statt an der Zauberleiste.", -- draft
	["Your swing timer as a small badge on your target's nameplate."] = "Dein Schwungtimer als kleines Abzeichen auf der Namensplakette deines Ziels.", -- draft
	["Over The Personal Display"] = "Über der persönlichen Anzeige", -- draft
	["The swing badge stands centred above the display instead of on your target's nameplate."] = "Das Schlagabzeichen steht mittig über der Anzeige statt auf der Namensplakette deines Ziels.", -- draft
	["Big Cooldowns"] = "Große Abklingzeiten", -- draft
	["Your big defensive cooldowns (Shield Wall, Evasion, Ice Block...) as icons above the health bar."] = "Deine großen defensiven Abklingzeiten (Schildwall, Entrinnen, Eisblock...) als Symbole über der Gesundheitsleiste.", -- draft
	["Tracked Spells"] = "Verfolgte Zauber", -- draft
	["Tick your class's spells to see them in a row under the bars while they last on you, each with its seconds. Nothing is ticked at first."] = "Hake Zauber deiner Klasse an, um sie in einer Reihe unter den Leisten zu sehen, solange sie auf dir wirken, jeden mit seinen Sekunden. Anfangs ist nichts angehakt.", -- draft
	["Track By Name"] = "Nach Namen verfolgen", -- draft
	["Type a buff or debuff's name (or its spell ID) to see it in the Tracked Spells row while it lasts on you, like a talent's proc. In a fight the game tells only some spells; those it keeps hidden show out of a fight."] = "Gib den Namen (oder die Zauber-ID) eines Stärkungs- oder Schwächungszaubers ein, um ihn in der Reihe der verfolgten Zauber zu sehen, solange er auf dir liegt, etwa den Effekt eines Talents. Im Kampf nennt das Spiel nur manche Zauber; verborgene zeigen sich außerhalb des Kampfes.", -- draft
	["Percent And Spell Text"] = "Prozent- und Zaubertext", -- draft
	["Health and power percent, spell names and times."] = "Gesundheit und Kraft in Prozent, Zaubernamen und Zeiten.", -- draft
	["Text Font"] = "Textschrift", -- draft
	["The font of the display's text. Shared: the interface font."] = "Die Schrift des Texts der Anzeige. Gemeinsam: die Oberflächenschrift.", -- draft
	["Class Colours"] = "Klassenfarben", -- draft
	["The health bar in your class colour instead of green."] = "Die Gesundheitsleiste in deiner Klassenfarbe statt grün.", -- draft
	["How wide the bars are."] = "Wie breit die Leisten sind.", -- draft
	["How tall the health bar is; the others follow."] = "Wie hoch die Gesundheitsleiste ist; die anderen folgen.", -- draft
	["Big Cooldown Size"] = "Größe der großen Abklingzeiten", -- draft
	["The size of the Big Cooldowns' icons."] = "Die Größe der Symbole der Großen Abklingzeiten.", -- draft
	["Follow Camera Zoom"] = "Kamerazoom folgen", -- draft
	["The display stays by your character as you zoom the camera."] = "Die Anzeige bleibt bei deinem Charakter, wenn du die Kamera zoomst.", -- draft
	["Cast Motion"] = "Zauberbewegung", -- draft
	["The cast bar opens, flashes on a landed cast and drops when interrupted."] = "Die Zauberleiste öffnet sich, blitzt bei einem gelandeten Zauber auf und fällt bei einer Unterbrechung.", -- draft
	["The health a hit took stays lit for a moment before it drains."] = "Die Gesundheit, die ein Treffer nahm, leuchtet kurz, bevor sie abläuft.", -- draft
	["Heal Lead"] = "Heilungsvorlauf", -- draft
	["A heal lights the health it gives at once; the bar then fills into it."] = "Eine Heilung lässt die gewährte Gesundheit sofort aufleuchten; die Leiste füllt sich dann hinein.", -- draft
	["Heavy Hit"] = "Schwerer Treffer", -- draft
	["A critical or crushing blow on you flashes the bars red."] = "Ein kritischer oder schmetternder Schlag auf dich lässt die Leisten rot aufblitzen.", -- draft
	["Power Spent"] = "Verbrauchte Ressource", -- draft
	["The power an ability costs stays lit for a moment, so you see the cost."] = "Die Kraft, die eine Fähigkeit kostet, leuchtet kurz, damit du die Kosten siehst.", -- draft
	["Power Gained"] = "Gewonnene Ressource", -- draft
	["New power lights up ahead of the bar before it fills."] = "Neue Kraft leuchtet vor der Leiste auf, bevor sie sich füllt.", -- draft
	["Dodge, Parry, Block"] = "Ausweichen, Parieren, Blocken", -- draft
	["Your dodge, parry or block flicks its word off the health bar."] = "Dein Ausweichen, Parieren oder Blocken schnellt als Wort von der Gesundheitsleiste.", -- draft
	["Low Health"] = "Niedrige Gesundheit", -- draft
	["The health bar turns ember under 35% health."] = "Die Gesundheitsleiste wird unter 35% Gesundheit glutrot.", -- draft
	["Loss Of Control"] = "Kontrollverlust", -- draft
	["While you are stunned, feared or silenced, the bars turn red and a line counts down its time. Replaces the game's own banner."] = "Solange du betäubt, verängstigt oder zum Schweigen gebracht bist, werden die Leisten rot und eine Linie zählt die Zeit herunter. Ersetzt das Banner des Spiels.", -- draft
	["Combat Settle"] = "Ruhe nach dem Kampf", -- draft
	["The bars rise into place when a fight starts and settle lower and slimmer after it. (To fade them out of combat: the Fader.)"] = "Die Leisten steigen zu Kampfbeginn an ihren Platz und setzen sich danach tiefer und schmaler. (Zum Ausblenden außerhalb des Kampfes: der Ausblender.)", -- draft
	["Plays a short sample fight on the display."] = "Spielt einen kurzen Beispielkampf auf der Anzeige.", -- draft
	["a shield going up, hit, low and broken, casts, and the bars in the fight"] = "ein Schild entsteht, wird getroffen, schwach und zerbricht, Zauber und die Balken im Kampf", -- draft
	-- VoiceOver
	["Voice Over"] = "Voice Over", -- draft
	["Reads NPC dialog, quests and books aloud: recorded voices from the voice pack, or text-to-speech."] = "Liest NPC-Dialoge, Quests und Bücher vor: aufgenommene Stimmen aus dem Stimmenpaket oder Sprachausgabe.", -- draft
	["Every quest giver speaks. Recorded voices with the pack, text-to-speech without it."] = "Jeder Questgeber spricht. Aufgenommene Stimmen mit dem Paket, Sprachausgabe ohne es.", -- draft
	["Read Aloud"] = "Vorlesen", -- draft
	["NPC Greetings"] = "NPC-Begrüßungen", -- draft
	["What an NPC says when you talk to them."] = "Was ein NPC sagt, wenn du mit ihm sprichst.", -- draft
	["Quest Offers"] = "Questangebote", -- draft
	["The quest's description when it is offered."] = "Die Beschreibung der Quest, wenn sie angeboten wird.", -- draft
	["Quest Objectives"] = "Questziele", -- draft
	["The quest's objectives after its description, when the voice pack has them recorded."] = "Die Ziele der Quest nach ihrer Beschreibung, wenn das Stimmenpaket sie aufgenommen hat.", -- draft
	["Quest Progress"] = "Questfortschritt", -- draft
	["What the NPC says when you return with an unfinished quest."] = "Was der NPC sagt, wenn du mit einer unfertigen Quest zurückkommst.", -- draft
	["Quest Turn-In"] = "Questabgabe", -- draft
	["What the NPC says when you hand in a quest."] = "Was der NPC sagt, wenn du eine Quest abgibst.", -- draft
	["Read Books And Letters Aloud"] = "Bücher und Briefe vorlesen", -- draft
	["Books, letters, notes and signs read aloud when you open them."] = "Bücher, Briefe, Notizen und Schilder werden beim Öffnen vorgelesen.", -- draft
	["Text-to-Speech"] = "Sprachausgabe", -- draft
	["Male NPCs"] = "Männliche NPCs", -- draft
	["The text-to-speech voice for male NPCs. Add voices in Windows' speech settings."] = "Die Sprachausgabe-Stimme für männliche NPCs. Füge Stimmen in den Spracheinstellungen von Windows hinzu.", -- draft
	["Automatic (by gender)"] = "Nach Geschlecht", -- draft
	["Female NPCs"] = "Weibliche NPCs", -- draft
	["The text-to-speech voice for female NPCs."] = "Die Sprachausgabe-Stimme für weibliche NPCs.", -- draft
	["Speed"] = "Geschwindigkeit", -- draft
